   {modal?.type==='staffcertification'&&!isOwner&&<CertificatePhotoForm definition={s.certificationTypes.find(t=>t.id===(certPrefill?.certification_type_id||focusedCert?.certification_type_id))} key={focusedCert?.id||certPrefill?.needId} previous={focusedCert} prefill={certPrefill} today={s.today} busy={busy} save={async f=>{f.set('action','staffCertificate');await run(f,'Certificate photo saved. Certification training status updated.');}}/>}
   {modal?.type==='certification'&&<CertificationForm data={s} saveName={async(body,message)=>run(body,message,false)} key={focusedCert?.id||certPrefill?.memberId+':'+certPrefill?.title} previous={focusedCert} prefill={certPrefill} staff={staff} today={s.today} busy={busy} save={async f=>{f.set('action','certification');if(focusedCert)f.set('replacesId',focusedCert.id);await run(f,focusedCert?'Renewal recorded. Previous certificate retained.':'Certification saved.');}}/>}
