 const hidden=doc?.staff_access==='not_viewable',draft=data.revisions.find(r=>r.document_id===doc?.id&&r.status==='draft'),existingRoles=data.trainingNeeds.filter(n=>n.document_id===doc?.id&&n.kind==='document').map(n=>data.trainingRoles.find(r=>r.id===n.role_id)?.name).filter(Boolean);
