 {type==='assign'&&<Field label="Training type"><Pick value={kind} onChange={setKind} label="Schedule training type" options={[{value:'document',label:'Read document / view video'},{value:'certification',label:'Certification / recertification'}]}/></Field>}
 {kind==='certification'?<><CertificationPicker data={data} value={certification} setValue={setCertification} busy={busy} save={saveName}/><Field label="Renewal alert before expiry (days)"><Input type="number" name="renewalLeadDays" required min={1} max={365} defaultValue={60}/></Field></>:doc?<div className="form-note"><strong>{doc.title}</strong><p>{doc.code} · {type==='release'?'Revision '+(draft?.version||'')+' awaiting approval':'Current released revision'}</p></div>:<Field label="Released document or video"><Pick value={documentId} onChange={setDocumentId} label="Choose released document or video" options={documents}/></Field>}
 {type==='release'&&<>{existingRoles.length>0&&<p className="form-note">Existing role requirements automatically receive this revision: {existingRoles.join(', ')}. Their schedules remain unchanged. Edit or remove them under Training needs by role.</p>}<DocumentRoleTraining data={data} plan={rolePlan} setPlan={setRolePlan} busy={busy}/>{rolePlan?.required&&hidden&&<p className="warning-banner">Enable staff viewing before adding required role training.</p>}</>}
