function CertificationForm({data,saveName,previous,prefill,staff,today,busy,save}:{data:AppState;saveName:(body:any,message:string)=>Promise<any>;previous?:Certification;prefill?:{memberId:string;title:string;reminderDays:number;certification_type_id?:string|null};staff:Member[];today:string;busy:boolean;save:(f:FormData)=>Promise<void>}){
 const [memberId,setMemberId]=useState(prefill?.memberId||previous?.member_id||staff[0]?.id||''),[file,setFile]=useState<File|null>(null);
 const [certification,setCertification]=useState(()=>initialCertificationSelection(data,prefill||previous));
 return <form className="modal-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),choice=certificationSelection(data,certification);f.set('memberId',memberId);f.set('title',choice.title);f.set('certificationTypeId',choice.certificationTypeId);if(file)f.set('file',file);await save(f);}}><Field label="Staff member"><Pick value={memberId} onChange={setMemberId} label="Certification staff member" options={staff.map(m=>({value:m.id,label:m.name}))}/></Field><CertificationPicker data={data} value={certification} setValue={setCertification} busy={busy} save={saveName}/><div className="form-grid"><Field label="Issuing organization"><Input name="issuer" required defaultValue={previous?.issuer||''}/></Field><Field label="Certificate / registration number"><Input name="number" defaultValue={previous?.number||''}/></Field></div><div className="form-grid"><Field label="Issued date"><Input type="date" name="issuedAt" required defaultValue={today}/></Field><Field label="Expiry date"><Input type="date" name="expiresAt" required defaultValue={shiftDate(today,365)}/></Field></div><Field label="Alert before expiry (days)" hint="An in-app alert starts this many days before expiry."><Input type="number" name="reminderDays" min={1} max={365} required defaultValue={prefill?.reminderDays||previous?.reminder_days||60}/></Field><p className="form-note">Staff must upload a certificate photo from their portal before certification training closes. Owner-entered details or attachments alone do not close training.</p><Field label="Owner attachment (optional)"><Input type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" onChange={e=>setFile(e.target.files?.[0]||null)}/></Field>{previous&&<p className="form-note">The previous certification remains in renewal history after this record is saved.</p>}<div className="dialog-actions"><Button disabled={busy||!memberId||!certification} type="submit">{busy?'Saving…':previous?'Save renewal':'Save certification'}</Button></div></form>;
}
function exportAudit(s:AppState){const cell=(v:string)=>'"'+(/^[=+@\-\t\r]/.test(v)?"'"+v:v).replaceAll('"','""')+'"';const lines=[['Timestamp','Actor','Action','Details'],...s.audit.map(a=>[a.created_at,a.actor,a.action,a.detail])].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([lines],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='DocTrain-Activity-'+s.today+'.csv';a.click();URL.revokeObjectURL(url);}
